import{_ as t,o as r,c as l,ag as o}from"./chunks/framework.D7Pdja0E.js";const c=JSON.parse('{"title":"태스크","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/tasks.md","filePath":"02-user-guide/tasks.md","lastUpdated":1776993543000}'),e={name:"02-user-guide/tasks.md"};function i(n,a,s,h,d,u){return r(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="태스크" tabindex="-1">태스크 <a class="header-anchor" href="#태스크" aria-label="Permalink to &quot;태스크&quot;">​</a></h1><p>토픽 내에서 태스크를 생성하고 관리합니다. 칸반 보드와 간트 차트 두 가지 뷰를 제공합니다.</p><h2 id="태스크-보기" tabindex="-1">태스크 보기 <a class="header-anchor" href="#태스크-보기" aria-label="Permalink to &quot;태스크 보기&quot;">​</a></h2><p>토픽 상세 화면 &gt; <strong>태스크</strong> 탭을 선택합니다. 상단의 토글로 뷰를 전환합니다:</p><ul><li><strong>보드</strong>: 칸반 스타일 (할 일 → 진행중 → 검토 → 완료)</li><li><strong>간트차트</strong>: 타임라인 기반 일정 뷰</li></ul><h2 id="태스크-생성" tabindex="-1">태스크 생성 <a class="header-anchor" href="#태스크-생성" aria-label="Permalink to &quot;태스크 생성&quot;">​</a></h2><h3 id="보드에서-생성" tabindex="-1">보드에서 생성 <a class="header-anchor" href="#보드에서-생성" aria-label="Permalink to &quot;보드에서 생성&quot;">​</a></h3><ol><li>원하는 상태 컬럼의 <strong>&quot;+&quot;</strong> 버튼을 클릭합니다.</li><li>제목, 설명, 우선순위, 담당자, 마감일을 입력합니다.</li></ol><h3 id="메시지에서-생성" tabindex="-1">메시지에서 생성 <a class="header-anchor" href="#메시지에서-생성" aria-label="Permalink to &quot;메시지에서 생성&quot;">​</a></h3><p>메시지 액션 메뉴 &gt; **&quot;태스크 만들기&quot;**를 클릭하면 메시지 내용이 태스크 설명에 자동 입력됩니다.</p><h3 id="캘린더에서-빠른-생성" tabindex="-1">캘린더에서 빠른 생성 <a class="header-anchor" href="#캘린더에서-빠른-생성" aria-label="Permalink to &quot;캘린더에서 빠른 생성&quot;">​</a></h3><p>나의 태스크 &gt; 캘린더 뷰에서 날짜 셀을 클릭하면 빠른 생성 팝오버가 표시됩니다. 제목과 프로젝트/토픽을 선택하여 즉시 태스크를 생성할 수 있습니다.</p><h2 id="태스크-상태" tabindex="-1">태스크 상태 <a class="header-anchor" href="#태스크-상태" aria-label="Permalink to &quot;태스크 상태&quot;">​</a></h2><table tabindex="0"><thead><tr><th>상태</th><th>설명</th></tr></thead><tbody><tr><td>할 일 (todo)</td><td>아직 시작하지 않은 태스크</td></tr><tr><td>진행중 (in_progress)</td><td>현재 작업 중</td></tr><tr><td>검토 (review)</td><td>검토 대기 중</td></tr><tr><td>완료 (done)</td><td>완료된 태스크</td></tr></tbody></table><h2 id="태스크-우선순위" tabindex="-1">태스크 우선순위 <a class="header-anchor" href="#태스크-우선순위" aria-label="Permalink to &quot;태스크 우선순위&quot;">​</a></h2><table tabindex="0"><thead><tr><th>우선순위</th><th>색상</th></tr></thead><tbody><tr><td>긴급</td><td>빨강</td></tr><tr><td>높음</td><td>주황</td></tr><tr><td>보통</td><td>파랑</td></tr><tr><td>낮음</td><td>회색</td></tr></tbody></table><h2 id="작업일지-work-log" tabindex="-1">작업일지 (Work Log) <a class="header-anchor" href="#작업일지-work-log" aria-label="Permalink to &quot;작업일지 (Work Log)&quot;">​</a></h2><p>태스크에 실제 작업 시간을 기록합니다. 계획 대비 실적을 추적하여 프로젝트 진행 현황을 파악할 수 있습니다.</p><h3 id="작업일지-작성" tabindex="-1">작업일지 작성 <a class="header-anchor" href="#작업일지-작성" aria-label="Permalink to &quot;작업일지 작성&quot;">​</a></h3><ol><li>태스크 상세 또는 나의 태스크 &gt; 작업일지 탭에서 **&quot;+ 작업일지 추가&quot;**를 클릭합니다.</li><li>작업 날짜, 시작 시간, 종료 시간을 입력합니다.</li><li>작업 내용(메모)을 입력합니다.</li><li>시간은 자동으로 계산됩니다 (예: 09:00~18:00 = 8시간).</li></ol><h3 id="초과근무-표시" tabindex="-1">초과근무 표시 <a class="header-anchor" href="#초과근무-표시" aria-label="Permalink to &quot;초과근무 표시&quot;">​</a></h3><p>표준 근무시간을 초과하는 작업은 자동으로 초과근무로 표시됩니다.</p><h3 id="간트-차트에서-작업일지-시각화" tabindex="-1">간트 차트에서 작업일지 시각화 <a class="header-anchor" href="#간트-차트에서-작업일지-시각화" aria-label="Permalink to &quot;간트 차트에서 작업일지 시각화&quot;">​</a></h3><p>간트 차트에서 태스크 바 위에 실제 작업일지가 블록으로 표시됩니다:</p><ul><li><strong>계획 기간</strong>: 태스크의 시작일~마감일 (바 전체)</li><li><strong>실제 작업</strong>: 작업일지 블록이 시간대별로 오버레이</li><li>시간 단위 줌 레벨에서 시작/종료 시간까지 상세하게 표시됩니다.</li></ul><h2 id="간트-차트" tabindex="-1">간트 차트 <a class="header-anchor" href="#간트-차트" aria-label="Permalink to &quot;간트 차트&quot;">​</a></h2><h3 id="타임라인-뷰" tabindex="-1">타임라인 뷰 <a class="header-anchor" href="#타임라인-뷰" aria-label="Permalink to &quot;타임라인 뷰&quot;">​</a></h3><ul><li><strong>시간별 / 일별 / 주별 / 월별</strong> 줌 레벨을 전환할 수 있습니다.</li><li>오늘 날짜는 빨간 점선으로 표시됩니다.</li><li><strong>오늘로 이동</strong> 버튼으로 현재 날짜 위치로 스크롤합니다.</li><li>줌 레벨 변경 시 <strong>자동으로 오늘 위치로 스크롤</strong>됩니다.</li><li><strong>시간별 뷰</strong>는 오늘 ±7일 범위로 제한되고, 진입 시 오늘 12시를 중앙에 표시합니다.</li></ul><h3 id="태스크-바-드래그" tabindex="-1">태스크 바 드래그 <a class="header-anchor" href="#태스크-바-드래그" aria-label="Permalink to &quot;태스크 바 드래그&quot;">​</a></h3><ul><li><strong>좌우 드래그</strong>: 태스크의 시작일/종료일을 변경합니다.</li><li><strong>좌우 끝 드래그</strong>: 시작일 또는 종료일만 개별 변경합니다.</li></ul><h3 id="순서-변경" tabindex="-1">순서 변경 <a class="header-anchor" href="#순서-변경" aria-label="Permalink to &quot;순서 변경&quot;">​</a></h3><p>좌측 태스크 목록에서 드래그 핸들을 잡고 위아래로 드래그하면 순서가 변경됩니다. 변경된 순서는 서버에 자동 저장됩니다.</p><h3 id="태스크-편집" tabindex="-1">태스크 편집 <a class="header-anchor" href="#태스크-편집" aria-label="Permalink to &quot;태스크 편집&quot;">​</a></h3><p>태스크 이름을 클릭하면 편집 팝오버가 열립니다:</p><ul><li>제목, 설명, 상태, 우선순위, 날짜 수정</li><li>마일스톤 설정</li><li><strong>의존성 관리</strong>: 선행 태스크를 추가/삭제할 수 있습니다.</li></ul><h3 id="의존성-선행-태스크" tabindex="-1">의존성 (선행 태스크) <a class="header-anchor" href="#의존성-선행-태스크" aria-label="Permalink to &quot;의존성 (선행 태스크)&quot;">​</a></h3><p>태스크 간의 선후 관계를 설정하면 간트 차트에 화살표로 표시됩니다.</p><ol><li>태스크 편집에서 <strong>의존성</strong> 섹션의 <strong>&quot;추가&quot;</strong> 버튼을 클릭합니다.</li><li>선행 태스크를 선택합니다.</li><li>삭제하려면 의존성 목록의 휴지통 아이콘을 클릭합니다.</li></ol><h3 id="리소스-간트-자원-관리" tabindex="-1">리소스 간트 (자원 관리) <a class="header-anchor" href="#리소스-간트-자원-관리" aria-label="Permalink to &quot;리소스 간트 (자원 관리)&quot;">​</a></h3><p>프로젝트 멤버별 작업 현황을 리소스 간트 차트로 확인할 수 있습니다:</p><ul><li>멤버별 배정된 태스크 바 표시</li><li>작업일지 블록 오버레이로 계획 대비 실적 비교</li><li>계획 공수(man-day) 대비 실제 투입 시간 리포트</li></ul><h2 id="나의-태스크" tabindex="-1">나의 태스크 <a class="header-anchor" href="#나의-태스크" aria-label="Permalink to &quot;나의 태스크&quot;">​</a></h2><p>사이드바 &gt; <strong>나의 태스크</strong>를 클릭하면 나에게 배정된 전체 태스크를 확인할 수 있습니다.</p><h3 id="요약-통계" tabindex="-1">요약 통계 <a class="header-anchor" href="#요약-통계" aria-label="Permalink to &quot;요약 통계&quot;">​</a></h3><p>상단에 현재 태스크 현황이 표시됩니다:</p><ul><li>할 일 / 진행중 / 검토 / 완료 / 지연 건수</li></ul><h3 id="날짜-프리셋-칩" tabindex="-1">날짜 프리셋 칩 <a class="header-anchor" href="#날짜-프리셋-칩" aria-label="Permalink to &quot;날짜 프리셋 칩&quot;">​</a></h3><p>요약 카드 아래에 빠른 날짜 필터 칩이 있습니다:</p><ul><li><strong>전체</strong> / <strong>오늘</strong> / <strong>이번 주</strong> / <strong>이번 달</strong> / <strong>지연</strong> / <strong>마감임박(7일)</strong></li><li>칩 클릭 한 번으로 마감일 기준 필터링</li></ul><h3 id="표시-옵션" tabindex="-1">표시 옵션 <a class="header-anchor" href="#표시-옵션" aria-label="Permalink to &quot;표시 옵션&quot;">​</a></h3><p>필터 영역 우측에 두 개의 체크박스:</p><ul><li><strong>완료 숨김</strong> (기본 ON) — 완료된 태스크를 목록에서 숨깁니다.</li><li><strong>프로젝트별 그룹</strong> (기본 ON) — 태스크를 프로젝트별 헤더로 묶어 표시합니다. 끄면 하나의 평면 목록이 됩니다.</li></ul><blockquote><p>표시 옵션은 브라우저에 저장되어 다음 접속 시에도 유지됩니다.</p></blockquote><h3 id="필터" tabindex="-1">필터 <a class="header-anchor" href="#필터" aria-label="Permalink to &quot;필터&quot;">​</a></h3><ul><li><strong>검색</strong> — 태스크 제목으로 검색</li><li><strong>우선순위</strong> — 긴급/높음/보통/낮음</li><li><strong>프로젝트</strong> — 특정 프로젝트의 태스크만</li><li><strong>토픽</strong> — 프로젝트의 세부 토픽. 드롭다운 내에서 <strong>진행중</strong> → <strong>완료</strong> 순으로 자동 그룹화</li></ul><h3 id="테이블-정렬" tabindex="-1">테이블 정렬 <a class="header-anchor" href="#테이블-정렬" aria-label="Permalink to &quot;테이블 정렬&quot;">​</a></h3><p>테이블 뷰에서 컬럼 헤더(태스크명/상태/우선순위/마감일)를 클릭하면 해당 기준으로 정렬됩니다. 같은 헤더를 다시 클릭하면 오름차순/내림차순이 전환되며, 정렬 상태는 브라우저에 저장됩니다.</p><h3 id="뷰-모드" tabindex="-1">뷰 모드 <a class="header-anchor" href="#뷰-모드" aria-label="Permalink to &quot;뷰 모드&quot;">​</a></h3><p>세 가지 뷰 모드를 전환할 수 있습니다:</p><ul><li><strong>테이블 뷰</strong>: 태스크 목록을 테이블 형태로 표시. 컬럼 헤더 클릭으로 정렬 가능.</li><li><strong>간트 차트 뷰</strong>: 나에게 배정된 태스크를 타임라인에 표시. 시간별 뷰는 오늘 ±7일로 제한.</li><li><strong>캘린더 뷰</strong>: 월별 캘린더에 마감일 기준으로 태스크 표시. 날짜 클릭으로 빠른 태스크 생성 가능.</li></ul><h3 id="인라인-편집" tabindex="-1">인라인 편집 <a class="header-anchor" href="#인라인-편집" aria-label="Permalink to &quot;인라인 편집&quot;">​</a></h3><p>테이블 뷰에서 상태, 우선순위, 마감일을 클릭하여 즉시 변경할 수 있습니다.</p>',62)])])}const b=t(e,[["render",i]]);export{c as __pageData,b as default};
